package android.opengl;
import org.padtv.bridge.EGLNative;
public final class EGL14 {
 public static final int EGL_DEFAULT_DISPLAY=0,EGL_NONE=12344,EGL_RED_SIZE=12324,EGL_GREEN_SIZE=12323,EGL_BLUE_SIZE=12322,EGL_ALPHA_SIZE=12321,EGL_DEPTH_SIZE=12325,EGL_STENCIL_SIZE=12326,EGL_RENDERABLE_TYPE=12352,EGL_OPENGL_ES2_BIT=4,EGL_SURFACE_TYPE=12339,EGL_PBUFFER_BIT=1,EGL_WINDOW_BIT=4,EGL_CONTEXT_CLIENT_VERSION=12440,EGL_WIDTH=12375,EGL_HEIGHT=12374,EGL_SUCCESS=12288,EGL_VENDOR=12371,EGL_VERSION=12372,EGL_EXTENSIONS=12373;
 public static final EGLDisplay EGL_NO_DISPLAY=new EGLDisplay(0);public static final EGLContext EGL_NO_CONTEXT=new EGLContext(0);public static final EGLSurface EGL_NO_SURFACE=new EGLSurface(0,null,0,0);
 private static long id(EGLObjectHandle o){return o==null?0:o.handle;}
 private static void slot(int[] a,int o){if(a==null||o<0||o>=a.length)throw new IllegalArgumentException("EGL array bounds");}
 public static EGLDisplay eglGetDisplay(int display){if(display!=0)throw new UnsupportedOperationException("Only default EGL display");return new EGLDisplay(EGLNative.display());}
 public static boolean eglInitialize(EGLDisplay d,int[] major,int mo,int[] minor,int mi){if(major!=null)slot(major,mo);if(minor!=null)slot(minor,mi);int[] v=EGLNative.initialize(id(d));if(v==null)return false;if(major!=null)major[mo]=v[0];if(minor!=null)minor[mi]=v[1];return true;}
 public static boolean eglChooseConfig(EGLDisplay d,int[] attrs,int offset,EGLConfig[] configs,int co,int size,int[] num,int no){slot(num,no);if(size<0||size>128||configs==null||co<0||co>configs.length-size)throw new IllegalArgumentException("EGL configuration bounds");long[] found=EGLNative.configs(id(d),attrs,offset,size);if(found==null)return false;num[no]=found.length;for(int i=0;i<found.length;i++)configs[co+i]=new EGLConfig(found[i]);return true;}
 public static EGLContext eglCreateContext(EGLDisplay d,EGLConfig c,EGLContext shared,int[] attrs,int offset){return new EGLContext(EGLNative.context(id(d),id(c),id(shared),attrs,offset));}
 public static EGLSurface eglCreatePbufferSurface(EGLDisplay d,EGLConfig c,int[] attrs,int offset){int w=0,h=0;if(attrs!=null)for(int i=offset;i+1<attrs.length&&attrs[i]!=EGL_NONE;i+=2){if(attrs[i]==EGL_WIDTH)w=attrs[i+1];if(attrs[i]==EGL_HEIGHT)h=attrs[i+1];}return new EGLSurface(EGLNative.pbuffer(id(d),id(c),attrs,offset),null,w,h);}
 public static EGLSurface eglCreateWindowSurface(EGLDisplay d,EGLConfig c,Object window,int[] attrs,int offset){if(attrs!=null&&(offset<0||offset>=attrs.length||attrs[offset]!=EGL_NONE))throw new UnsupportedOperationException("EGL window attributes are not implemented");android.view.Surface target=window instanceof android.view.Surface?(android.view.Surface)window:window instanceof android.view.SurfaceHolder?((android.view.SurfaceHolder)window).getSurface():null;if(target==null||!target.isValid())throw new IllegalArgumentException("Valid Surface required");int w=target.bridgeWidth(),h=target.bridgeHeight();int[] a={EGL_WIDTH,w,EGL_HEIGHT,h,EGL_NONE};return new EGLSurface(EGLNative.pbuffer(id(d),id(c),a,0),target,w,h);}
 public static boolean eglMakeCurrent(EGLDisplay d,EGLSurface draw,EGLSurface read,EGLContext context){return EGLNative.current(id(d),id(draw),id(read),id(context));}
 public static boolean eglSwapBuffers(EGLDisplay d,EGLSurface s){if(s.target!=null)s.target.bridgeRGBA(java.nio.ByteBuffer.wrap(EGLNative.pixels(s.width,s.height)),s.width,s.height);return EGLNative.swap(id(d),id(s));}
 public static boolean eglDestroySurface(EGLDisplay d,EGLSurface s){return EGLNative.destroy(id(d),id(s),4);}public static boolean eglDestroyContext(EGLDisplay d,EGLContext c){return EGLNative.destroy(id(d),id(c),3);}public static boolean eglTerminate(EGLDisplay d){return EGLNative.terminate(id(d));}public static int eglGetError(){return EGLNative.error();}public static String eglQueryString(EGLDisplay d,int name){return EGLNative.query(id(d),name);}
}
